const SnWinnersModalList = () => {
  const getMinuteSlot = () => Math.floor(Date.now() / 60000);
  const [slot, setSlot] = R.useState(getMinuteSlot);

  R.useEffect(() => {
    const id = setInterval(() => {
      const cur = getMinuteSlot();
      setSlot(prev => (prev !== cur ? cur : prev));
    }, 1000);
    return () => clearInterval(id);
  }, []);

  const winners = R.useMemo(() => {
    let seed = (slot ^ 0x9e3779b9) >>> 0;
    const rand = () => {
      seed = (seed + 0x6d2b79f5) >>> 0;
      let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
    const shuffle = (arr) => {
      const copy = [...arr];
      for (let i = copy.length - 1; i > 0; i--) {
        const j = Math.floor(rand() * (i + 1));
        const tmp = copy[i];
        copy[i] = copy[j];
        copy[j] = tmp;
      }
      return copy;
    };
    const toBnDigits = (val) => {
      const bn = ["০", "১", "২", "৩", "৪", "৫", "৬", "৭", "৮", "৯"];
      return String(val).replace(/\d/g, d => bn[Number(d)]);
    };

    const prefixes = shuffle([
      "ra", "sh", "na", "ka", "ta", "sa", "ri", "fa", "ar", "ma",
      "su", "ah", "im", "ja", "ni", "al", "me", "ru", "bi", "mo",
      "ha", "so", "zi", "em", "ak", "tu", "ro", "as", "pa", "di",
      "ju", "si", "ba", "re", "fo", "ya", "za", "mu", "kh", "ru"
    ]).slice(0, 5);

    const games = shuffle([
      "Aviator", "Super Ace", "Crazy Time", "Fortune Gems", "Money Coming",
      "Boxing King", "Mega Ace", "Golden Empire", "Sweet Bonanza", "Sugar Rush",
      "Gates of Olympus", "Dragon Tiger", "Lightning Roulette", "Baccarat Deluxe",
      "Jungle King", "Mines", "777 Classic", "Coin Volcano", "Wild Bounty", "Mega Wheel"
    ]).slice(0, 5);

    const suffixPool = new Set();
    while (suffixPool.size < 5) {
      const n = Math.floor(rand() * 90) + 10;
      suffixPool.add(String(n));
    }
    const suffixes = Array.from(suffixPool);

    const amounts = [];
    const tierRanges = [
      [38000, 76000],
      [26000, 37500],
      [19000, 25500],
      [13500, 18800],
      [8500, 13200]
    ];
    for (let i = 0; i < 5; i++) {
      const [minA, maxA] = tierRanges[i];
      const raw = minA + rand() * (maxA - minA);
      const rounded = Math.round(raw / 50) * 50;
      amounts.push(rounded);
    }
    amounts.sort((a, b) => b - a);

    return prefixes.map((p, i) => ({
      u: p + "***" + suffixes[i],
      g: games[i],
      amt: "৳" + toBnDigits(amounts[i].toLocaleString("en-IN"))
    }));
  }, [slot]);

  return o.jsx(o.Fragment, {
    children: winners.map((w, ix) =>
      o.jsxs("div", {
        style: {
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
          padding: "10px 12px",
          background: "#f8fafc",
          border: "1px solid #e2e8f0",
          borderRadius: "12px"
        },
        children: [
          o.jsxs("div", {
            children: [
              o.jsx("div", { style: { fontWeight: 800, fontSize: "13.5px", color: "#0f172a" }, children: w.u }),
              o.jsx("div", { style: { fontSize: "11.5px", color: "#64748b" }, children: w.g })
            ]
          }),
          o.jsx("div", {
            style: { fontWeight: 800, fontSize: "14px", color: "#059669", fontVariantNumeric: "tabular-nums" },
            children: w.amt
          })
        ]
      }, slot + "-" + ix)
    )
  });
};
